// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/assets/real-estate/issuance/orders", wrapper.CreateIssuanceOrder)
	router.GET(options.BaseURL+"/assets/real-estate/issuance/orders/:orderRef", wrapper.FetchIssuanceOrder)
	router.GET(options.BaseURL+"/assets/real-estates/active", wrapper.GetActiveRealEstates)
	router.GET(options.BaseURL+"/assets/real-estates/:id", wrapper.GetRealEstateById)
	router.POST(options.BaseURL+"/auth/sign-in", wrapper.PostAuthSignIn)
	router.POST(options.BaseURL+"/auth/sign-up", wrapper.PostAuthSignUp)
	router.POST(options.BaseURL+"/contract/identity", wrapper.CreateIdentity)
	router.POST(options.BaseURL+"/contract/identity/claims/add", wrapper.AddClaimToIdentity)
	router.POST(options.BaseURL+"/contract/token", wrapper.CreateTokenContract)
	router.POST(options.BaseURL+"/contract/token/burn", wrapper.BurnTokenAsync)
	router.POST(options.BaseURL+"/contract/token/mint", wrapper.MintTokenAsync)
	router.GET(options.BaseURL+"/contract/token/:tokenAddress/infos", wrapper.GetTokenInfos)
	router.GET(options.BaseURL+"/health", wrapper.GetHealth)
	router.POST(options.BaseURL+"/payments/add", wrapper.PaymentAdd)
	router.POST(options.BaseURL+"/trex/init/authority/configure", wrapper.ConfigureAuthority)
	router.POST(options.BaseURL+"/trex/init/contract/factory/identity", wrapper.DeployIdentityFactory)
	router.POST(options.BaseURL+"/trex/init/contract/factory/trexFactory", wrapper.DeployAndInitTrexFactoryAsync)
	router.POST(options.BaseURL+"/trex/init/implementations", wrapper.DeployAllImplementationsAsync)
	router.POST(options.BaseURL+"/trex/init/suite/deploy", wrapper.DeployTrexSuiteAsync)
	router.GET(options.BaseURL+"/trex/suite", wrapper.GetTrexSuiteInfos)
	router.GET(options.BaseURL+"/user/:userId", wrapper.GetUserById)
	router.DELETE(options.BaseURL+"/users/:userId/favorites/real-estates/:realEstateId", wrapper.RemoveFavoritesRealEstateForUser)
	router.POST(options.BaseURL+"/users/:userId/favorites/real-estates/:realEstateId", wrapper.AddFavoritesRealEstateForUser)
}

